// Import necessary components
include "node_modules/circomlib/circuits/comparators.circom";
include "node_modules/circomlib/circuits/arithmetic/binary.circom";

// Template for quicksort partition logic
template quicksort_partition_logic() {
    // Signal declarations
    signal input a0, a1, a2, a3, a4, a5, a6, low, high;
    signal pivot, i, swaps, arr[7], j, cond, swap;
    signal output out;

    // Component templates
    component GreaterEqThan = GreaterEqThan(2);
    component Binary = Binary();

    // Initialize pivot as the middle element
    pivot <== (a0 + a1 + a2 + a3 + a4 + a5 + a6) / 7;

    // Initialize i and swaps
    i <== low - 1;
    swaps <== 0;

    // Loop logic (unrolled for 7 iterations)
    for (var j = 0; j < 7; j++) {
        // Calculate cond as a binary value (0 or 1)
        cond <== GreaterEqThan(arr[j], pivot).out;

        // Update i and swaps
        i <== i + cond;
        swaps <== swaps + cond;

        // Swap arr[i] and arr[j] if cond is 1
        arr[j] <== (1 - cond) * arr[j] + cond * arr[i];
        arr[i] <== (1 - cond) * arr[i] + cond * arr[j];
    }

    // Final swap
    swap <== Binary(arr[i + 1], arr[high]).out;
    arr[i + 1] <== arr[i + 1] * (1 - swap) + swap * arr[high];
    arr[high] <== arr[high] * (1 - swap) + swap * arr[i + 1];

    // Calculate out
    out <== (i + 1) * 100 + swaps;
}

// Component main
component main = quicksort_partition_logic();

