template shuffle_integrity_logic() {
  signal input c0;
  signal input c1;
  signal input c2;
  signal input c3;
  signal input c4;
  signal input s0;
  signal input s1;
  signal input s2;
  signal input s3;
  signal input s4;
  signal input sd;
  signal output out;

  // Check if sum of c equals sum of s
  signal sum_c = c0 + c1 + c2 + c3 + c4;
  signal sum_s = s0 + s1 + s2 + s3 + s4;
  component eq_sum = Equal(64);
  eq_sum.in[0] <== sum_c;
  eq_sum.in[1] <== sum_s;
  signal eq_sum_out <== eq_sum.out;

  // Check if sum of squares of c equals sum of squares of s
  signal square_c0 = c0 * c0;
  signal square_c1 = c1 * c1;
  signal square_c2 = c2 * c2;
  signal square_c3 = c3 * c3;
  signal square_c4 = c4 * c4;
  signal sum_square_c = square_c0 + square_c1 + square_c2 + square_c3 + square_c4;
  signal square_s0 = s0 * s0;
  signal square_s1 = s1 * s1;
  signal square_s2 = s2 * s2;
  signal square_s3 = s3 * s3;
  signal square_s4 = s4 * s4;
  signal sum_square_s = square_s0 + square_s1 + square_s2 + square_s3 + square_s4;
  component eq_square_sum = Equal(64);
  eq_square_sum.in[0] <== sum_square_c;
  eq_square_sum.in[1] <== sum_square_s;
  signal eq_square_sum_out <== eq_square_sum.out;

  // Check if s0 is in c
  signal is_s0_in_c = (s0 == c0) || (s0 == c1) || (s0 == c2) || (s0 == c3) || (s0 == c4);
  signal iv = is_s0_in_c * 100;

  // Calculate inversions
  signal inv_s0_s1 = (s0 > s1) * 1;
  signal inv_s0_s2 = (s0 > s2) * 1;
  signal inv_s0_s3 = (s0 > s3) * 1;
  signal inv_s0_s4 = (s0 > s4) * 1;
  signal inv_s1_s2 = (s1 > s2) * 1;
  signal inv_s1_s3 = (s1 > s3) * 1;
  signal inv_s1_s4 = (s1 > s4) * 1;
  signal inv_s2_s3 = (s2 > s3) * 1;
  signal inv_s2_s4 = (s2 > s4) * 1;
  signal inv_s3_s4 = (s3 > s4) * 1;
  signal inversions = inv_s0_s1 + inv_s0_s2 + inv_s0_s3 + inv_s0_s4 + inv_s1_s2 + inv_s1_s3 + inv_s1_s4 + inv_s2_s3 + inv_s2_s4 + inv_s3_s4;

  // Output
  component and = And(2);
  and.in[0] <== eq_sum_out;
  and.in[1] <== eq_square_sum_out;
  signal and_out = and.out;
  out = and_out * (inversions + iv);
}

