template iterated_game_memory_score() {
    signal input p1;
    signal input p2;
    signal input h1;
    signal input h2;
    signal input h3;
    signal input r;
    signal output out;

    // Constants
    signal constant ZERO = 0;
    signal constant ONE = 1;
    signal constant THREE = 3;
    signal constant FIVE = 5;
    signal constant HUNDRED = 100;
    signal constant TWENTY = 20;
    signal constant FIFTY = 50;
    signal constant FIVE_COMP = 5; // For comparison

    // Range checks (Rule 14)
    component p1_range = Num2Bits(2);
    p1_range.in <== p1;

    component p2_range = Num2Bits(2);
    p2_range.in <== p2;

