    // Condition 1: p1 == 1 && p2 == 1
    component eq_p1_1 = IsEqual();
    eq_p1_1.in[0] <== p1;
    eq_p1_1.in[1] <== ONE;

    component eq_p2_1 = IsEqual();
    eq_p2_1.in[0] <== p2;
    eq_p2_1.in[1] <== ONE;

    signal cond1 <== eq_p1_1.out * eq_p2_1.out; // AND gate (Rule 8)

    // Condition 2: p1 == 1 && p2 == 0
    component eq_p2_0 = IsEqual();
    eq_p2_0.in[0] <== p2;
    eq_p2_0.in[1] <== ZERO;

    signal cond2 <== eq_p1_1.out * eq_p2_0.out;

    // Condition 3: p1 == 0 && p2 == 1
    component eq_p1_0 = IsEqual();
    eq_p1_0.in[0] <== p1;
    eq_p1_0.in[1] <== ZERO;

    signal cond3 <== eq_p1_0.out * eq_p2_1.out;

    // Priority chain for bp (Rule 9)
    signal isCase1 <== cond1;
    signal isCase2 <== (1 - isCase1) * cond2;
    signal isCase3 <== (1 - isCase1) * (1 - isCase2) * cond3;
    signal isDefault <== (1 - isCase1) * (1 - isCase2) * (1 - isCase3);

    // bp value selection (Rule 15)
    signal bp_case1 <== isCase1 * THREE;
    signal bp_case2 <== isCase2 * ZERO;
    signal bp_case3 <== isCase3 * FIVE;
    signal bp_default <== isDefault * ONE;

    signal bp <== bp_case1 + bp_case2 + bp_case3 + bp_default;

    // ts calculation
    signal ts <== h1 + h2 + h3;

    // pe calculation: (p1 == 0 && r > 5) ? 1 : 0
    component gt_r_5 = GreaterThan(64);
    gt_r_5.in[0] <== r;
    gt_r_5.in[1] <== FIVE_COMP;

    signal cond_pe <== eq_p1_0.out * gt_r_5.out;

    // Mux for pe (Rule 15)
    signal pe <== cond_pe * (ONE - ZERO) + ZERO;

    // fs calculation
    signal bp_term <== bp * HUNDRED;
    signal ts_term <== ts * TWENTY;
    signal pe_term <== pe * FIFTY;

    signal fs_raw <== bp_term + ts_term - pe_term;

    // Clamp to 0 if negative (Rule 4, Rule 15)
    component is_negative = LessThan(64);
    is_negative.in[0] <== fs_raw;
    is_negative.in[1] <== ZERO;

    // Note: In field arithmetic, we need to check if fs_raw < 0
    // Since we can't directly compare to 0, we use LessThan
    // But actually fs_raw < 0 means fs_raw > P/2 in field terms
    // Let's use a safer approach with Num2Bits

