    // Check if fs_raw is negative by looking at the highest bit
    // For 64-bit numbers, if the 63rd bit is 1, it's negative
    // But in field arithmetic, we need a different approach

    // Alternative: Use LessThan to check if fs_raw < 0
    // Actually, we want to check if fs_raw < 0, but in field terms
    // we can check if fs_raw > P/2

    // Let's use a simpler approach: if fs_raw < 0, return 0, else return fs_raw
    // We'll use the comparator approach

    component lt_zero = LessThan(64);
    lt_zero.in[0] <== fs_raw;
    lt_zero.in[1] <== ZERO;

    // Since we're in a prime field, we need to be careful with negative numbers
    // Let's use the absolute value shielding approach (Rule 5)

    // Extract sign (simplified for this use case)
    // We'll use a different approach: check if subtraction would underflow

    // Actually, for this specific case, we can use:
    // out = (fs_raw < 0) ? 0 : fs_raw
    // But we need to implement the comparison properly

    // Let's use the standard approach with LessThan
    // signal is_negative <== LessThan(64)(fs_raw, 0);

    // Since we can't pass 0 directly to LessThan (it's a signal),
    // we need to create a zero signal

    signal zero_signal <== 0;

    component is_fs_negative = LessThan(64);
