template iterated_game_memory_score() {
    // Public inputs
    signal input p1;
    signal input p2;
    signal input h1;
    signal input h2;
    signal input h3;
    signal input r;

    // Output
    signal output out;

    // Private witnesses
    signal bp;
    signal ts;
    signal pe;
    signal fs;
    signal fs_lt_zero;
    signal fs_sel;

    // Intermediate signals for conditions
    signal cond_p1_eq_1;
    signal cond_p2_eq_1;
    signal cond_p1_eq_0;
    signal cond_p2_eq_0;
    signal cond_r_gt_5;
    signal cond_p1_eq_1_and_p2_eq_1;
    signal cond_p1_eq_1_and_p2_eq_0;
    signal cond_p1_eq_0_and_p2_eq_1;
    signal cond_p1_eq_0_and_r_gt_5;

    // Condition computations
    // p1 == 1
    signal p1_minus_1 <== p1 - 1;
    cond_p1_eq_1 <== p1_minus_1 * p1_minus_1 === 0 ? 1 : 0;

    // p2 == 1
    signal p2_minus_1 <== p2 - 1;
    cond_p2_eq_1 <== p2_minus_1 * p2_minus_1 === 0 ? 1 : 0;

    // p1 == 0
    cond_p1_eq_0 <== p1 * p1 === 0 ? 1 : 0;

    // p2 == 0
    cond_p2_eq_0 <== p2 * p2 === 0 ? 1 : 0;

    // r > 5
    component r_gt_5 = GreaterThan(64);
    r_gt_5.in[0] <== r;
    r_gt_5.in[1] <== 5;
    cond_r_gt_5 <== r_gt_5.out;

    // Combined conditions
    cond_p1_eq_1_and_p2_eq_1 <== cond_p1_eq_1 * cond_p2_eq_1;
    cond_p1_eq_1_and_p2_eq_0 <== cond_p1_eq_1 * cond_p2_eq_0;
    cond_p1_eq_0_and_p2_eq_1 <== cond_p1_eq_0 * cond_p2_eq_1;
    cond_p1_eq_0_and_r_gt_5 <== cond_p1_eq_0 * cond_r_gt_5;

    // Base points calculation
    bp <== cond_p1_eq_1_and_p2_eq_1 * 3 
         + cond_p1_eq_1_and_p2_eq_0 * 0 
         + cond_p1_eq_0_and_p2_eq_1 * 5 
         + (1 - cond_p1_eq_1_and_p2_eq_1 - cond_p1_eq_1_and_p2_eq_0 - cond_p1_eq_0_and_p2_eq_1) * 1;

    // Total score
    ts <== h1 + h2 + h3;

    // Penalty
    pe <== cond_p1_eq_0_and_r_gt_5;

    // Final score
    fs <== (bp * 100) + (ts * 20) - (pe * 50);

    // Check if final score is less than zero
    component fs_lt_zero_check = LessThan(64);
    fs_lt_zero_check.in[0] <== fs;
    fs_lt_zero_check.in[1] <== 0;
    fs_lt_zero <== fs_lt_zero_check.out;

    // Selector for final output
    fs_sel <== fs_lt_zero;

    // Final output (max of 0 and fs)
    out <== fs_sel * (0 - fs) + fs;

    // Constraints
    // Binary constraints for condition signals
    cond_p1_eq_1 * (cond_p1_eq_1 - 1) === 0;
    cond_p2_eq_1 * (cond_p2_eq_1 - 1) === 0;
    cond_p1_eq_0 * (cond_p1_eq_0 - 1) === 0;
    cond_p2_eq_0 * (cond_p2_eq_0 - 1) === 0;
    cond_r_gt_5 * (cond_r_gt_5 - 1) === 0;

    // Combined condition constraints
    cond_p1_eq_1_and_p2_eq_1 === cond_p1_eq_1 * cond_p2_eq_1;
    cond_p1_eq_1_and_p2_eq_0 === cond_p1_eq_1 * cond_p2_eq_0;
    cond_p1_eq_0_and_p2_eq_1 === cond_p1_eq_0 * cond_p2_eq_1;
    cond_p1_eq_0_and_r_gt_5 === cond_p1_eq_0 * cond_r_gt_5;

    // Main computation constraints
    bp === cond_p1_eq_1_and_p2_eq_1 * 3 
        + cond_p1_eq_1_and_p2_eq_0 * 0 
        + cond_p1_eq_0_and_p2_eq_1 * 5 
        + (1 - cond_p1_eq_1_and_p2_eq_1 - cond_p1_eq_1_and_p2_eq_0 - cond_p1_eq_0_and_p2_eq_1) * 1;

    ts === h1 + h2 + h3;
    pe === cond_p1_eq_0_and_r_gt_5;
    fs === (bp * 100) + (ts * 20) - (pe * 50);

    // Binary constraint for fs_lt_zero
    fs_lt_zero * (fs_lt_zero - 1) === 0;
    fs_sel === fs_lt_zero;
    out === fs_sel * (0 - fs) + fs;
}

