// Integer division template with proper constraints
template IntegerDiv() {
    signal input numerator;
    signal input denominator;
    signal output quotient;
    signal output remainder;

    // Compute quotient and remainder (witness generation)
    quotient <-- numerator \ denominator;
    remainder <-- numerator % denominator;

    // Constraints
    denominator * quotient + remainder === numerator;
    remainder < denominator;
    remainder >= 0;
}

// Check if a signal is non-positive (≤ 0)
template IsNonPositive(n) {
    signal input in;
    signal output isNonPositive;

    // Use comparator to check if in ≤ 0
    component lt = LessEqThan(n);
    lt.in[0] <== in;
    lt.in[1] <== 0;
    isNonPositive <== lt.out;
}

// Main ANOVA F-test template
template ANOVA_F_Test(n) {
    // n is the bit width for comparisons (e.g., 64 for i64)
    signal input g1s;
    signal input g1n;
    signal input g2s;
    signal input g2n;
    signal input tss;

    signal output result;

    // 1. Calculate means with integer division
    // Mean of group 1: m1 = g1s / g1n
    component div1 = IntegerDiv();
    div1.numerator <== g1s;
    div1.denominator <== g1n;
    signal m1;
    m1 <== div1.quotient;

    // Mean of group 2: m2 = g2s / g2n
    component div2 = IntegerDiv();
    div2.numerator <== g2s;
    div2.denominator <== g2n;
    signal m2;
    m2 <== div2.quotient;

    // Grand mean: gm = (g1s + g2s) / (g1n + g2n)
    signal total_sum = g1s + g2s;
    signal total_count = g1n + g2n;

    component div3 = IntegerDiv();
    div3.numerator <== total_sum;
    div3.denominator <== total_count;
    signal gm;
    gm <== div3.quotient;

    // 2. Calculate differences from grand mean
    signal m1_minus_gm = m1 - gm;
    signal m2_minus_gm = m2 - gm;

    // 3. Square differences
    signal m1_minus_gm_sq = m1_minus_gm * m1_minus_gm;
    signal m2_minus_gm_sq = m2_minus_gm * m2_minus_gm;

    // 4. Weighted sum of squares (Between-group SS)
    signal g1n_times_sq1 = g1n * m1_minus_gm_sq;
    signal g2n_times_sq2 = g2n * m2_minus_gm_sq;
    signal ssb = g1n_times_sq1 + g2n_times_sq2;

    // 5. Within-group sum of squares
    signal ssw = tss - ssb;

    // 6. Check if ssw ≤ 0
    component check_nonpos = IsNonPositive(n);
    check_nonpos.in <== ssw;
    signal ssw_nonpos = check_nonpos.isNonPositive;

    // Binary constraint for ssw_nonpos
    ssw_nonpos * (1 - ssw_nonpos) === 0;

    // Additional constraints for ssw_nonpos
    // If ssw_nonpos = 1, then ssw ≤ 0
    // If ssw_nonpos = 0, then ssw > 0
    component check_positive = LessThan(n);
    check_positive.in[0] <== 0;
    check_positive.in[1] <== ssw;
    signal ssw_positive = check_positive.out;

    // Constraint: ssw_nonpos = 1 - ssw_positive
    ssw_nonpos === 1 - ssw_positive;

    // 7. Calculate quotient when ssw > 0
    signal ssb_times_100 = ssb * 100;
    signal quotient;

    // Only perform division if ssw > 0
    // We'll use a conditional constraint
    signal denominator_safe = ssw + ssw_nonpos; // Add 1 if ssw = 0 to avoid division by zero

    component div4 = IntegerDiv();
    div4.numerator <== ssb_times_100;
    div4.denominator <== denominator_safe;
    quotient <== div4.quotient;

    // Constraint: if ssw_nonpos = 1, quotient should be 0
    // if ssw_nonpos = 0, quotient = (ssb * 100) / ssw
    quotient * (1 - ssw_nonpos) === (ssb_times_100 - div4.remainder) * (1 - ssw_nonpos) / denominator_safe;

    // 8. Conditional result
    // result = ssw_nonpos * gm + (1 - ssw_nonpos) * (quotient + gm)
    signal adjusted = quotient + gm;
    result <== ssw_nonpos * gm + (1 - ssw_nonpos) * adjusted;

    // Alternative implementation using selector
    // result = gm + (1 - ssw_nonpos) * quotient
    // This is equivalent to the above but simpler
    // result <== gm + (1 - ssw_nonpos) * quotient;
}

// Example main component for testing
component main {public [g1s, g1n, g2s, g2n, tss]} = ANOVA_F_Test(64);

