template EMA() {
    signal input p0;
    signal input p1;
    signal input p2;
    signal input p3;
    signal input p4;
    signal output out;

    // Constants
    var ALPHA = 40;
    var ONE_HUNDRED = 100;
    var SIXTY = 60;

    // Helper function for EMA calculation
    component emaCalc = EMAIteration();

    // Initial EMA (p0 * 100)
    signal ema0;
    ema0 <== p0 * ONE_HUNDRED;

    // EMA iterations
    signal ema1 <== emaCalc.ema_out(p1, ema0);
    signal ema2 <== emaCalc.ema_out(p2, ema1);
    signal ema3 <== emaCalc.ema_out(p3, ema2);
    signal ema4 <== emaCalc.ema_out(p4, ema3);

    // Output
    out <== ema4;
}

// Helper template for a single EMA iteration
template EMAIteration() {
    signal input price;
    signal input prev_ema;
    signal output ema_out;

    var ALPHA = 40;
    var ONE_HUNDRED = 100;
    var SIXTY = 60;

    // p_i × α
    signal temp1;
    temp1 <== price * ALPHA;

    // ema_{i-1} × (100 - α) = ema_{i-1} × 60
    signal temp2;
    temp2 <== prev_ema * SIXTY;

    // Integer division: temp2 ÷ 100
    // Represent as: temp2 = 100 * q + r, where 0 ≤ r < 100
    signal q;
    signal r;

    // Division constraint: temp2 = 100 * q + r
    temp2 === q * ONE_HUNDRED + r;

    // Range constraint: 0 ≤ r < 100
    r < ONE_HUNDRED;

    // Final EMA calculation
    ema_out <== temp1 + q;
}

component main = EMA();

