template shuffle_integrity_logic() {
    signal input c0, c1, c2, c3, c4;
    signal input s0, s1, s2, s3, s4;
    signal output out;

    // Compute sum of original and shuffled
    signal sc = c0 + c1 + c2 + c3 + c4;
    signal ss = s0 + s1 + s2 + s3 + s4;

    // Compute sum of squares of original and shuffled
    signal qc = c0*c0 + c1*c1 + c2*c2 + c3*c3 + c4*c4;
    signal qs = s0*s0 + s1*s1 + s2*s2 + s3*s3 + s4*s4;

    // Check if sums and sum of squares are equal (permutation check)
    signal is_permutation = (sc === ss) * (qc === qs);

    // Since permutation check passed implies s0 is in original list,
    // bonus is 100 if valid permutation, 0 otherwise
    signal bonus = is_permutation * 100;

    // Compute number of inversions in shuffled sequence
    signal inv_count = 0;

    component comp01 = GreaterThan(64);
    comp01.in[0] <== s0;
    comp01.in[1] <== s1;
    signal inv01 <== comp01.out;

    component comp02 = GreaterThan(64);
    comp02.in[0] <== s0;
    comp02.in[1] <== s2;
    signal inv02 <== comp02.out;

    component comp03 = GreaterThan(64);
    comp03.in[0] <== s0;
    comp03.in[1] <== s3;
    signal inv03 <== comp03.out;

    component comp04 = GreaterThan(64);
    comp04.in[0] <== s0;
    comp04.in[1] <== s4;
    signal inv04 <== comp04.out;

    component comp12 = GreaterThan(64);
    comp12.in[0] <== s1;
    comp12.in[1] <== s2;
    signal inv12 <== comp12.out;

    component comp13 = GreaterThan(64);
    comp13.in[0] <== s1;
    comp13.in[1] <== s3;
    signal inv13 <== comp13.out;

    component comp14 = GreaterThan(64);
    comp14.in[0] <== s1;
    comp14.in[1] <== s4;
    signal inv14 <== comp14.out;

    component comp23 = GreaterThan(64);
    comp23.in[0] <== s2;
    comp23.in[1] <== s3;
    signal inv23 <== comp23.out;

    component comp24 = GreaterThan(64);
    comp24.in[0] <== s2;
    comp24.in[1] <== s4;
    signal inv24 <== comp24.out;

    component comp34 = GreaterThan(64);
    comp34.in[0] <== s3;
    comp34.in[1] <== s4;
    signal inv34 <== comp34.out;

    signal total_inversions = inv01 + inv02 + inv03 + inv04 + 
