    // arr[t][k] corresponds to arrk_t in the pseudo-logic
    signal arr[8][7];

    // i[t] corresponds to i0..i7
    signal i[8];

    // s[t] corresponds to s0..s7
    signal s[8];

    // Per-iteration condition bits for j = 0..6
    signal ge_low[7];
    signal lt_high[7];
    signal le_pivot[7];
    signal active[7];
    signal take[7];

    // target[j][k] corresponds to target_j_k
    signal target[7][7];

    // picked[j] corresponds to picked_j
    signal picked[7];

    signal final_pos;

    // Initial array state
    arr[0][0] <== a0;
    arr[0][1] <== a1;
    arr[0][2] <== a2;
    arr[0][3] <== a3;
    arr[0][4] <== a4;
    arr[0][5] <== a5;
    arr[0][6] <== a6;

    // High selector bits h0..h6
    component eqHigh[7];
    for (var k = 0; k < 7; k++) {
        eqHigh[k] = IsEqual();
        eqHigh[k].in[0] <== high;
        eqHigh[k].in[1] <== k;
        h[k] <== eqHigh[k].out;
    }

    // Pivot selection
    pivot <== h[0] * a0 + h[1] * a1 + h[2] * a2 + h[3] * a3 + h[4] * a4 + h[5] * a5 + h[6] * a6;

    // Initial indices
    i[0] <== low - 1;
    s[0] <== 0;

    // Comparator components
    component geLowCmp[7];
    component ltHighCmp[7];
    component lePivotCmp[7];
    component targetEqCmp[7][7];

    for (var j = 0; j < 7; j++) {
        // ge_low_j = compare(j >= low)
        geLowCmp[j] = GreaterEqThan(64);
        geLowCmp[j].in[0] <== j;
        geLowCmp[j].in[1] <== low;
        ge_low[j] <== geLowCmp[j].out;

        // lt_high_j = compare(j < high)
        ltHighCmp[j] = LessThan(64);
        ltHighCmp[j].in[0] <== j;
        ltHighCmp[j].in[1] <== high;
        lt_high[j] <== ltHighCmp[j].out;

        // le_pivot_j = compare(arrj_j <= pivot)
        lePivotCmp[j] = LessEqThan(64);
        lePivotCmp[j].in[0] <== arr[j][j];
        lePivotCmp[j].in[1] <== pivot;
        le_pivot[j] <== lePivotCmp[j].out;

        active[j] <== ge_low[j] * lt_high[j];
        take[j] <== active[j] * le_pivot[j];

        // target_j_k = compare(i_j + 1 == k)
        for (var k = 0; k < 7; k++) {
            targetEqCmp[j][k] = IsEqual();
            targetEqCmp[j][k].in[0] <== i[j] + 1;
            targetEqCmp[j][k].in[1] <== k;
            target[j][k] <== targetEqCmp[j][k].out;
        }

        // picked_j
        picked[j] <==
            target[j][0] * arr[j][0] +
            target[j][1] * arr[j][1] +
            target[j][2] * arr[j][2] +
            target[j][3] * arr[j][3] +
            target[j][4] * arr[j][4] +
            target[j][5] * arr[j][5] +
            target[j][6] * arr[j][6];

        // Array transition arr[*]_{j+1}
        for (var k = 0; k < 7; k++) {
            if (k == j) {
                arr[j + 1][k] <== take[j] * picked[j] + (1 - take[j]) * arr[j][k];
            } else {
                arr[j + 1][k] <==
                    take[j] * (target[j][k] * arr[j][j] + (1 - target[j][k]) * arr[j][k]) +
                    (1 - take[j]) * arr[j][k];
            }
        }

        // Index / swap count transitions
        i[j + 1] <== i[j] + take[j];
        s[j + 1] <== s[j] + take[j];
    }

    final_pos <== i[7] + 1;
    out <== final_pos * 100 + s[7];
}

