    i <== i + swap_out;
    arr_out[i], arr_out[j] <== arr_out[j], arr_out[i];
    swaps <== swaps + swap_out;
    j <== j + 1;

    loop cond <== (j < 7) {
        cond <== (j < 7);
        arr_out <== arr;
        arr <== arr_out;
        cond <== (j >= low) * (j < high);
        swap_out <== cond * (arr[j] <= pivot);
