// Define the aave_v3_interest_logic template
template aave_v3_interest_logic() {
    // Input signals
    signal input d; // Debt amount
    signal input r; // Reserve factor
    signal input b; // Base interest rate
    signal input s1; // Interest rate multiplier 1
    signal input s2; // Interest rate multiplier 2

    // Output signal
    signal output out;

    // Check if reserve factor is zero
    component is_zero = IsZero(64);
    is_zero.in <== r;

    // Calculate utilization ratio
    component u = Div(64);
    u.in[0] <== d;
    u.in[1] <== r;

    // Determine interest rate based on utilization ratio
    component ir = Mul(64);
    ir.in[0] <== u.out;
    ir.in[1] <== s1;

    component ir2 = Mul(64);
    ir2.in[0] <== u.out;
    ir2.in[1] <== s2;

    component ir_selector = GreaterEqThan(64);
    ir_selector.in[0] <== u.out;
    ir_selector.in[1] <== 0.5;

    component ir_final = Mux(64);
    ir_final.in[0] <== ir.out;
    ir_final.in[1] <== ir2.out;
    ir_final.sel <== ir_selector.out;

    // Calculate interest accrued
    component br = Mul(64);
    br.in[0] <== ir_final.out;
    br.in[1] <== b;

    // Calculate supply rate
    component sr = Mul(64);
    sr.in[0] <== br.out;
    sr.in[1] <== u.out;

    // Calculate reserve premium
    component rp = Mul(64);
    rp.in[0] <== u.out;
    rp.in[1] <== s1;

    // Compute total interest
    component res = Add(64);
    res.in[0] <== br.out;
    res.in[1] <== sr.out;
    res.in[2] <== rp.out;

    // Cap total interest at 1,000,000
    component cap = GreaterEqThan(64);
    cap.in[0] <== res.out;
    cap.in[1] <== 1000000;

    component capped_res = Mux(64);
    capped_res.in[0] <== res.out;
    capped_res.in[1] <== 1000000;
    capped_res.sel <== cap.out;

    // Output the total interest
    out <== is_zero.out ? b : capped_res.out;
}

