template aave_v3_interest_logic() {
    signal input d;
    signal input r;
    signal input b;
    signal input s1;
    signal input s2;
    signal input opt;

    signal output out;

    // Check if r == 0
    component isRZero = IsZero();
    isRZero.in <== r;
    signal br;
    signal u;

    // Compute u = (d * 10000) / r, but only if r != 0
    // We'll use conditional logic via multiplexers based on isRZero.out

    // First compute d_times_10000 = d * 10000
    signal d_times_10000;
    d_times_10000 <== d * 10000;

    // Safe division: if r == 0, we don't care about u because we return b directly.
    // But Circom requires all signals to be defined, so we define u conditionally.
    // We'll compute u_div = d_times_10000 / r using IntegerDivide
    component divU = IntegerDivide(64);
    divU.dividend <== d_times_10000;
    divU.divisor <== r + isRZero.out; // avoid division by zero; when r=0, divisor=1, but result unused
    u <== divU.quotient;

    // Now compute br
    // Condition: u <= opt ?
    component cmp_u_opt = LessEqThan(64);
    cmp_u_opt.in[0] <== u;
    cmp_u_opt.in[1] <== opt;

    // Compute term1 = (u * s1) / opt
    signal term1;
    component divTerm1 = IntegerDivide(64);
    divTerm1.dividend <== u * s1;
    divTerm1.divisor <== opt + (1 - cmp_u_opt.out); // avoid div by zero; if not used, add 1
    term1 <== divTerm1.quotient;

    // Compute branch1: b + term1
    signal branch1;
    branch1 <== b + term1;

    // Compute term2a = u - opt
    signal term2a;
    term2a <== u - opt;

    // Compute term2b = (term2a * s2) / (10000 - opt)
    signal denom2;
    denom2 <== 10000 - opt;
    signal term2b;
    component divTerm2b = IntegerDivide(64);
    divTerm2b.dividend <== term2a * s2;
    divTerm2b.divisor <== denom2 + cmp_u_opt.out; // if u<=opt, this branch unused; avoid div by zero
    term2b <== divTerm2b.quotient;

    // Compute branch2: b + s1 + term2b
    signal branch2;
    branch2 <== b + s1 + term2b;

    // Select br = cmp_u_opt.out ? branch1 : branch2
    br <== cmp_u_opt.out * branch1 + (1 - cmp_u_opt.out) * branch2;

    // Compute sr = ((br * u * 9000) / 10000) / 10000
    signal temp_sr1;
    temp_sr1 <== br * u * 9000;

    signal temp_sr2;
    component divSr1 = IntegerDivide(64);
    divSr1.dividend <== temp_sr1;
    divSr1.divisor <== 10000;
    temp_sr2 <== divSr1.quotient;

    signal sr;
    component divSr2 = IntegerDivide(64);
    divSr2.dividend <== temp_sr2;
    divSr2.divisor <== 10000;
    sr <== divSr2.quotient;

    // Compute rp
    signal rp;

    // Check u > 9500
    component cmp_u_9500 = GreaterThan(64);
    cmp_u_9500.in[0] <== u;
    cmp_u_9500.in[1] <== 9500;

    // Check u > 8000
    component cmp_u_8000 = GreaterThan(64);
    cmp_u_8000.in[0] <== u;
    cmp_u_8000.in[1] <== 8000;

    // Compute rp_high = (u - 9500) * 100
    signal rp_high;
    rp_high <== (u - 9500) * 100;

    // Compute rp_mid = (u - 8000) * 20
    signal rp_mid;
    rp_mid <== (u - 8000) * 20;

    // rp = 
    //   if u > 9500: rp_high
    //   elif u > 8000: rp_mid
    //   else: 0
    signal cond_high;
    cond_high <== cmp_u_9500.out;

    signal cond_mid;
    // u > 8000 and not (u > 9500) => u in (8000, 9500]
    cond_mid <== cmp_u_8000.out * (1 - cmp_u_9500.out);

    rp <== cond_high * rp_high + cond_mid * rp_mid;

    // res = br + sr + rp
    signal res_unclamped;
    res_unclamped <== br + sr + rp;

    // Clamp to 1000000
    component cmp_res_limit = LessThan(64);
    cmp_res_limit.in[0] <== res_unclamped;
    cmp_res_limit.in[1] <== 1000000;

    out <== cmp_res_limit.out * res_unclamped + (1 - cmp_res_limit.out) * 1000000;

    // If r == 0, output should be b
    // So override out if r == 0
    out <== isRZero.out * b + (1 - isRZero.out) * out;
}

// Helper templates

template IsZero() {
    signal input in;
    signal output out;
    component cmp = EqualsZero(64);
    cmp.in <== in;
    out <== cmp.out;
}

template EqualsZero(n) {
    signal input in;
    signal output out;
    component lt = LessThan(n);
    lt.in[0] <== in;
    lt.in[1] <== 1;
    out <== lt.out;
}

template IntegerDivide(n) {
    signal input dividend;
    signal input divisor;
    signal output quotient;
    signal output remainder;

    quotient <-- dividend / divisor;
    remainder <-- dividend % divisor;

    dividend === quotient * divisor + remainder;
    // Constrain remainder to be non-negative and less than divisor
    // For simplicity, assume inputs are non-negative and divisor > 0
    component lt = LessThan(n);
    lt.in[0] <== remainder;
    lt.in[1] <== divisor;
    lt.out === 1;

    component ge = GreaterEqThan(n);
    ge.in[0] <== remainder;
    ge.in[1] <== 0;
    ge.out === 1;
}

