    signal isGt8000 <== uGt8000.out;

    signal rpHigh <== (u - KINK2) * 100;
    signal rpMid <== (u - KINK1) * 20;

    signal rp <
        == isGt9500 * rpHigh
         + (1 - isGt9500) * isGt8000 * rpMid;

    signal res <== br + sr + rp;

    // return (res > 1000000) ? 1000000 : res;
    component resGtCap = GreaterThan(64);
    resGtCap.in[0] <== res;
    resGtCap.in[1] <== CAP;
    signal isResGtCap <== resGtCap.out;

    signal cappedRes <== isResGtCap * CAP + (1 - isResGtCap) * res;

    // if (r == 0) return b; else return cappedRes;
    out <== isRZero * b + (1 - isRZero) * cappedRes;
}

