include "node_modules/circomlib/circuits/comparators.circom";

template quicksort_partition_logic() {
    signal input a0;
    signal input a1;
    signal input a2;
    signal input a3;
    signal input a4;
    signal input a5;
    signal input a6;
    signal input low;
    signal input high;
    signal output out;

    // Array elements
    signal arr[7];
    arr[0] <== a0;
    arr[1] <== a1;
    arr[2] <== a2;
    arr[3] <== a3;
    arr[4] <== a4;
    arr[5] <== a5;
    arr[6] <== a6;

    // Get pivot element at index high
    signal pivot;
    pivot <-- (high == 0) ? arr[0] : 
             (high == 1) ? arr[1] : 
             (high == 2) ? arr[2] : 
             (high == 3) ? arr[3] : 
             (high == 4) ? arr[4] : 
             (high == 5) ? arr[5] : arr[6];

    // Initialize i = low - 1
    signal i;
    i <== low - 1;

    // Initialize swap counter
    signal swaps;
    swaps <== 0;

    // Temporary signals for swapping
    signal temp_arr[7];
    temp_arr[0] <== arr[0];
    temp_arr[1] <== arr[1];
    temp_arr[2] <== arr[2];
    temp_arr[3] <== arr[3];
    temp_arr[4] <== arr[4];
    temp_arr[5] <== arr[5];
    temp_arr[6] <== arr[6];

    // Process each element from 0 to 6
    signal processed_arr[7][7]; // [iteration][index]
    signal processed_i[8];      // i after each iteration
    signal processed_swaps[8];  // swaps after each iteration

    // Initialize first state
    processed_i[0] <== i;
    processed_swaps[0] <== swaps;

    // Copy initial array to first iteration
    for (var idx = 0; idx < 7; idx++) {
        processed_arr[0][idx] <== temp_arr[idx];
    }

    // Loop through j from 0 to 6
    for (var j = 0; j < 7; j++) {
        // Check if j is within range [low, high)
        component low_check_le = LessEqThan(64);
        component high_check_lt = LessThan(64);

        low_check_le.in[0] <== low;
        low_check_le.in[1] <== j;
        high_check_lt.in[0] <== j;
        high_check_lt.in[1] <== high;

        signal in_range;
        in_range <== low_check_le.out * high_check_lt.out;

        // Get current arr[j]
        signal current_j_val;
        current_j_val <-- (j == 0) ? processed_arr[j][0] : 
                         (j == 1) ? processed_arr[j][1] : 
                         (j == 2) ? processed_arr[j][2] : 
                         (j == 3) ? processed_arr[j][3] : 
                         (j == 4) ? processed_arr[j][4] : 
                         (j == 5) ? processed_arr[j][5] : processed_arr[j][6];

        // Compare with pivot
        component le_pivot = LessEqThan(64);
        le_pivot.in[0] <== current_j_val;
        le_pivot.in[1] <== pivot;
        signal should_swap <== le_pivot.out;

        // Combined condition: in_range AND should_swap
        signal do_swap <== in_range * should_swap;

        // Calculate new i value
        signal new_i;
        new_i <== processed_i[j] + do_swap;

        // Calculate new swaps value
        signal new_swaps;
        new_swaps <== processed_swaps[j] + do_swap;

        // Copy array values to next iteration
        for (var idx = 0; idx < 7; idx++) {
            processed_arr[j+1][idx] <== processed_arr[j][idx];
        }

        // Perform swap if needed
        signal temp_i_plus_1_val;
        temp_i_plus_1_val <-- (processed_i[j]+1 == 0) ? processed_arr[j][0] : 
                             (processed_i[j]+1 == 1) ? processed_arr[j][1] : 
                             (processed_i[j]+1 == 2) ? processed_arr[j][2] : 
                             (processed_i[j]+1 == 3) ? processed_arr[j][3] : 
                             (processed_i[j]+1 == 4) ? processed_arr[j][4] : 
                             (processed_i[j]+1 == 5) ? processed_arr[j][5] : 
                             (processed_i[j]+1 == 6) ? processed_arr[j][6] : processed_arr[j][0];

        // Conditional swap logic
        signal new_j_val;
        signal new_i_plus_1_val;

        new_j_val <== do_swap * temp_i_plus_1_val + (1 - do_swap) * processed_arr[j][j];
        new_i_plus_1_val <== do_swap * processed_arr[j][j] + (1 - do_swap) * temp_i_plus_1_val;

        // Update array values if swap happens
        for (var idx = 0; idx < 7; idx++) {
            signal update_j <== (idx == j) ? do_swap : 0;
            signal update_i_plus_1 <== (idx == processed_i[j] + 1) ? do_swap : 0;

            processed_arr[j+1][idx] <== 
                processed_arr[j][idx] * (1 - update_j) * (1 - update_i_plus_1) +
                new_j_val * update_j +
                new_i_plus_1_val * update_i_plus_1;
        }

        processed_i[j+1] <== new_i;
        processed_swaps[j+1] <== new_swaps;
    }

    // Final swap between (i+1) and high
    signal final_i_plus_1 <== processed_i[7] + 1;

    // Get values at positions final_i_plus_1 and high
    signal val_at_final_i_plus_1;
    val_at_final_i_plus_1 <-- (final_i_plus_1 == 0) ? processed_arr[7][0] : 
                            (final_i_plus_1 == 1) ? processed_arr[7][1] : 
                            (final_i_plus_1 == 2) ? processed_arr[7][2] : 
                            (final_i_plus_1 == 3) ? processed_arr[7][3] : 
                            (final_i_plus_1 == 4) ? processed_arr[7][4] : 
                            (final_i_plus_1 == 5) ? processed_arr[7][5] : processed_arr[7][6];

    signal val_at_high;
    val_at_high <-- (high == 0) ? processed_arr[7][0] : 
                   (high == 1) ? processed_arr[7][1] : 
                   (high == 2) ? processed_arr[7][2] : 
                   (high == 3) ? processed_arr[7][3] : 
                   (high == 4) ? processed_arr[7][4] : 
                   (high == 5) ? processed_arr[7][5] : processed_arr[7][6];

    // Create final array after last swap
    signal final_arr[7];
    for (var idx = 0; idx < 7; idx++) {
        signal is_i_plus_1 <== (idx == final_i_plus_1) ? 1 : 0;
        signal is_high <== (idx == high) ? 1 : 0;

        final_arr[idx] <== 
            processed_arr[7][idx] * (1 - is_i_plus_1) * (1 - is_high) +
            val_at_high * is_i_plus_1 +
            val_at_final_i_plus_1 * is_high;
    }

    // Calculate result: (i + 1) * 100 + swaps
    out <== (final_i_plus_1) * 100 + processed_swaps[7];
}

