    sub_10000_opt.in[0] <== ten_thousand;
    sub_10000_opt.in[1] <== opt;

    // Calculate (u - opt) * s2
    component mul_u_opt_s2 = Mul();
    mul_u_opt_s2.in[0] <== sub_u_opt.out;
    mul_u_opt_s2.in[1] <== s2;

