    sub_u_9500.in[0] <== u;
    sub_u_9500.in[1] <== nine_five_hundred;

    // Calculate (u - 9500) * 100
    component mul_u_9500_100 = Mul();
    mul_u_9500_100.in[0] <== sub_u_9500.out;
    mul_u_9500_100.in[1] <== one_hundred;

    // Calculate u - 8000
    component sub_u_8000 = Sub();
    sub_u_8000.in[0] <== u;
    sub_u_8000.in[1] <== eight_thousand;

    // Calculate (u - 8000) * 20
    component mul_u_8000_20 = Mul();
    mul_u_8000_20.in[0] <== sub_u_8000.out;
    mul_u_8000_20.in[1] <== twenty;

    // Select rp based on conditions
    signal rp <== uGt9500 * mul_u_9500_100.out + (1 - uGt9500) * uGt8000 * mul_u_8000_20.out;

    // Calculate res = br + sr + rp
    component add_br_sr = Add();
