template iterated_game_memory_score() {
    // Input signals
    signal input p1;
    signal input p2;
    signal input h1;
    signal input h2;
    signal input h3;
    signal input r;

    // Output signal
    signal output fs;

    // Binary check for p1 and p2
    signal p1_is_binary <== p1 * (1 - p1);
    signal p2_is_binary <== p2 * (1 - p2);

    // Base Payoff (bp) calculation using discrete conditional mapping
    // Cases: (1,1)→3, (1,0)→0, (0,1)→5, (0,0)→1

    // Create flags for each action pair
    signal p1_eq_1 <== p1;
    signal p1_eq_0 <== 1 - p1;
    signal p2_eq_1 <== p2;
    signal p2_eq_0 <== 1 - p2;

    // Calculate each possible bp value weighted by its condition
    signal bp_case_11 <== p1_eq_1 * p2_eq_1 * 3;
    signal bp_case_10 <== p1_eq_1 * p2_eq_0 * 0;
    signal bp_case_01 <== p1_eq_0 * p2_eq_1 * 5;
    signal bp_case_00 <== p1_eq_0 * p2_eq_0 * 1;

    // Sum all cases to get bp (only one will be non-zero due to binary constraints)
    signal bp <== bp_case_11 + bp_case_10 + bp_case_01 + bp_case_00;

    // History Bonus (ts) calculation
    signal ts <== h1 + h2 + h3;

    // Penalty (pe) calculation: 1 if p1 == 0 and r > 5, else 0
    component gt = GreaterThan(32); // Assuming r fits in 32 bits
    gt.in[0] <== r;
    gt.in[1] <== 5;

    signal r_gt_5 <== gt.out;
    signal pe <== p1_eq_0 * r_gt_5;

    // Final Score calculation: fs = (bp × 100) + (ts × 20) - (pe × 50)
    signal bp_scaled <== bp * 100;
    signal ts_scaled <== ts * 20;
    signal pe_scaled <== pe * 50;

    signal raw_fs <== bp_scaled + ts_scaled - pe_scaled;

    // Non-negative clamping (max with 0)
    component is_negative = LessThan(32); // Assuming raw_fs fits in 32 bits
    is_negative.in[0] <== 0;
    is_negative.in[1] <== raw_fs;

    // If raw_fs is negative (0 > raw_fs), is_negative.out = 1, else 0
    signal negative_flag <== is_negative.out;

    // Select between 0 and raw_fs based on negative_flag
