/*  Template: AnovaFTestLogic
    Inputs:
        g1s, g1n – sum and count of group 1
        g2s, g2n – sum and count of group 2
        tss      – total sum of squares
    Output:
        out – the resulting statistic (gm if the within‑group SS ≤ 0,
              otherwise (ssb·100)/ssw + gm)
*/
template AnovaFTestLogic() {
    /* ---------- inputs ---------- */
    signal input g1s;
    signal input g1n;
    signal input g2s;
    signal input g2n;
    signal input tss;

    signal output out;

    /* ---------- 1. means of the two groups ---------- */
    component divM1 = Div(252);
    divM1.a <== g1s;
    divM1.b <== g1n;
    signal m1 <== divM1.q;                 // m1 = g1s / g1n

    component divM2 = Div(252);
    divM2.a <== g2s;
    divM2.b <== g2n;
    signal m2 <== divM2.q;                 // m2 = g2s / g2n

    /* ---------- 2. grand mean ---------- */
    signal sumS <== g1s + g2s;             // Σ xi
    signal sumN <== g1n + g2n;             // Σ ni

    component divGM = Div(252);
    divGM.a <== sumS;
    divGM.b <== sumN;
    signal gm <== divGM.q;                 // gm = (g1s+g2s)/(g1n+g2n)

    /* ---------- 3. between‑group sum of squares ---------- */
    signal diff1 <== m1 - gm;               // (m1‑gm)
    signal diff2 <== m2 - gm;               // (m2‑gm)

    signal diff1Sq <== diff1 * diff1;       // (m1‑gm)²
    signal diff2Sq <== diff2 * diff2;       // (m2‑gm)²

    signal ssb1 <== g1n * diff1Sq;          // n1·(m1‑gm)²
    signal ssb2 <== g2n * diff2Sq;          // n2·(m2‑gm)²
    signal ssb   <== ssb1 + ssb2;           // ssb

    /* ---------- 4. within‑group sum of squares ---------- */
    signal ssw <== tss - ssb;               // ssw = tss – ssb

    /* ---------- 5. decide whether ssw ≤ 0 (zero or negative) ---------- */
    // zero‑check
    component isZeroSSW = IsZero();
    isZeroSSW.in <== ssw;

    // sign‑bit (most‑significant bit of the 254‑bit field representation)
    component bitsSSW = Num2Bits(254);
    bitsSSW.in <== ssw;
    signal signBit <== bitsSSW.out[253];    // 1 ⇒ negative in the field

    // OR of “zero” and “negative”
    signal shouldReturnGM <== isZeroSSW.out + signBit
                           - isZeroSSW.out * signBit;
    signal sswGTZero <== 1 - shouldReturnGM;   // 1 ⇒ ssw > 0

    /* ---------- 6. safe divisor (avoid zero / negative) ---------- */
    // When ssw ≤ 0 we substitute 1 so that the Div component never sees 0
    signal sswSafe <== sswGTZero * ssw + (1 - sswGTZero);

    /* ---------- 7. quotient = (ssb·100) / ssw ---------- */
    component divRes = Div(252);
    divRes.a <== ssb * 100;                 // dividend
    divRes.b <== sswSafe;                   // divisor (always > 0)
    signal quotient <== divRes.q;           // integer division result

    /* ---------- 8. final mux (if‑then‑else) ---------- */
    // out = shouldReturnGM ? gm : (quotient + gm)
    out <== shouldReturnGM * gm
         + sswGTZero * (quotient + gm);
}

/* ---------- main component ---------- */
component main = AnovaFTestLogic();

