    num <== 3 * bal * ts;

    // Witness for quotient and remainder
    // When ta == 0, force q = 0 and r = 0
    q <-- ta != 0 ? (3 * bal * ts) \ ta : 0;
    r <-- ta != 0 ? (3 * bal * ts) % ta : 0;

    p <== q;

    // Range constraints for q and r
    component q_bits = Num2Bits(qBits);
    q_bits.in <== q;

    component r_bits = Num2Bits(inBits);
    r_bits.in <== r;

    // Enforce division relation only when ta != 0:
    // num = ta * q + r
    is_ta_nonzero * (num - ta * q - r) === 0;

    // Force q = 0 and r = 0 when ta == 0
