template validator_slashing_weight(nBits) {
    signal input bal;
    signal input ts;
    signal input ta;

    signal output out;

    // Zero-check
    signal isZeroTa;
    signal nonZeroTa;
    signal taSafe;

    // Numerator
    signal t1;
    signal num;

    // Division witness
    signal q;
    signal r;

    // Min selection
    signal lt_bal;
    signal min_q_bal;

    // ta == 0 ?
    component iz = IsZero();
    iz.in <== ta;
    isZeroTa <== iz.out;
    nonZeroTa <== 1 - isZeroTa;

    // Safe denominator:
    // - if ta != 0, taSafe = ta
    // - if ta == 0, taSafe = 1
    taSafe <== ta + isZeroTa;

    // num = 3 * bal * ts
    t1 <== bal * ts;
    num <== 3 * t1;

    // Witness hints for quotient and remainder
    // If ta == 0, force q = 0 and r = 0 via the multiplier nonZeroTa.
    q <-- nonZeroTa * (num \ taSafe);
    r <-- nonZeroTa * (num % taSafe);

    // Range constraints
    component balBits = Num2Bits(nBits);
    balBits.in <== bal;

    component tsBits = Num2Bits(nBits);
    tsBits.in <== ts;

    component taBits = Num2Bits(nBits);
    taBits.in <== ta;

    component qBits = Num2Bits(nBits);
    qBits.in <== q;

    component rBits = Num2Bits(nBits);
    rBits.in <== r;

    // Enforce q = 0 and r = 0 when ta == 0
    isZeroTa * q === 0;
    isZeroTa * r === 0;

    // Enforce division relation when ta != 0:
    // num = ta * q + r
    nonZeroTa * (num - ta * q - r) === 0;

    // Enforce remainder bound:
    // if ta != 0 => r < ta
    // if ta == 0 => r < 1, which holds since r = 0
    component rLtTaSafe = LessThan(nBits);
    rLtTaSafe.in[0] <== r;
    rLtTaSafe.in[1] <== taSafe;
    rLtTaSafe.out === 1;

    // lt_bal = 1 iff q < bal
    component qLtBal = LessThan(nBits);
    qLtBal.in[0] <== q;
    qLtBal.in[1] <== bal;
    lt_bal <== qLtBal.out;

    // min(q, bal)
    min_q_bal <== bal + lt_bal * (q - bal);

    // out = 0 if ta == 0, else min(q, bal)
    out <== nonZeroTa * min_q_bal;
}

component main = validator_slashing_weight(64);

