template fixed_point_swap_slippage() {
    signal input ai;
    signal input ri;
    signal input ro;
    signal input tb;
    signal input e;
    signal output out;

    // Calculate f = (ai * tb) / 10000
    signal f <-- (ai * tb) \ 10000;

    // Calculate ae = ai - f
    signal ae <-- ai - f;

    // Calculate ao = (ae * ro) / (ri + ae)
    signal denominator <-- ri + ae;
    signal ao_temp <-- (ae * ro) \ denominator;
    signal ao <== ao_temp;

    // Apply exponential decay: ao = (ao * 9995) / 10000 for e iterations
    signal decay_factor <-- 9995;
    signal decay_divisor <-- 10000;

    // Create loop using component instantiation
    component decay[e];
    for (var i = 0; i < e; i++) {
        decay[i] = FixedPointMulDiv();
        if (i == 0) {
            decay[i].in[0] <== ao;
        } else {
            decay[i].in[0] <== decay[i-1].out;
        }
        decay[i].in[1] <== decay_factor;
        decay[i].in[2] <== decay_divisor;
    }

    signal final_ao;
    if (e > 0) {
        final_ao <== decay[e-1].out;
    } else {
        final_ao <== ao;
    }

    // Check if final_ao < 0 and return 0 if true, else return final_ao
    component lt = LessThan(64);
    lt.in[0] <== final_ao;
    lt.in[1] <== 0;

    signal is_negative <== lt.out;

    // out = is_negative ? 0 : final_ao
    out <== (1 - is_negative) * final_ao;
}

template FixedPointMulDiv() {
    signal input in[3]; // [numerator, multiplier, divisor]
    signal output out;

    // out = (in[0] * in[1]) / in[2]
    signal product <-- in[0] * in[1];
    out <-- product \ in[2];
}

component main = fixed_point_swap_slippage();

template stack_rpn_calculator() {
    // Declaration of signals and components
    signal input o0;
    signal input o1;
    signal input o2;
    signal input o3;
    signal input o4;
    signal output out;
    component stack[5];
    component top;

    // Statements
    for (var i = 0; i < 5; i++) {
        stack[i].in[0] <== o0;
        stack[i].in[1] <== o1;
        stack[i].in[2] <== o2;
        stack[i].in[3] <== o3;
        stack[i].in[4] <== o4;
        stack[i].out <== stack[i].in;
    }

    // Create a component for the top of the stack
    top.in[0] <== stack[0].out;
    top.in[1] <== stack[1].out;
    top.in[2] <== stack[2].out;
    top.in[3] <== stack[3].out;
    top.in[4] <== stack[4].out;

    // Define the operations
    component add = GreaterEqThan(64);
    component sub = GreaterEqThan(64);
    component mul = GreaterEqThan(64);

    // Assign the operations
    add.in[0] <== top.out[0];
    add.in[1] <== top.out[1];
    add.out <== add.in;
    sub.in[0] <== top.out[0];
    sub.in[1] <== top.out[1];
    sub.out <== sub.in;
    mul.in[0] <== top.out[0];
    mul.in[1] <== top.out[1];
    mul.out <== mul.in;

    // Define the output
    out <== 0;
    for (var i = 0; i < 5; i++) {
        if (o0 == i + 1) {
            out <== top.out[i];
        }
        if (o1 == i + 1) {
            out <== top.out[i];
        }
        if (o2 == i + 1) {
            out <== top.out[i];
        }
        if (o3 == i + 1) {
            out <== top.out[i];
        }
        if (o4 == i + 1) {
            out <== top.out[i];
        }
    }
    if (o0 == -1) {
        out <== add.out;
    }
    if (o0 == -2) {
        out <== sub.out;
    }
    if (o0 == -3) {
        out <== mul.out;
    }
}
