template iterated_game_memory_score() {
    signal input p1;
    signal input p2;
    signal input h1;
    signal input h2;
    signal input h3;
    signal input r;

    signal output out;

    // Equality checks for current actions
    component p1_is_0 = IsEqual();
    component p1_is_1 = IsEqual();
    component p2_is_0 = IsEqual();
    component p2_is_1 = IsEqual();

    p1_is_0.in[0] <== p1;
    p1_is_0.in[1] <== 0;

    p1_is_1.in[0] <== p1;
    p1_is_1.in[1] <== 1;

    p2_is_0.in[0] <== p2;
    p2_is_0.in[1] <== 0;

    p2_is_1.in[0] <== p2;
    p2_is_1.in[1] <== 1;

    // Payoff table selection
    signal case11 <== p1_is_1.out * p2_is_1.out; // (1,1) -> 3
    signal case10 <== p1_is_1.out * p2_is_0.out; // (1,0) -> 0
    signal case01 <== p1_is_0.out * p2_is_1.out; // (0,1) -> 5
    signal case00 <== p1_is_0.out * p2_is_0.out; // (0,0) -> 1

    signal bp <== 3 * case11 + 0 * case10 + 5 * case01 + 1 * case00;

    // History total
    signal ts <== h1 + h2 + h3;

    // Penalty indicator: p1 = 0 and r > 5
    component r_gt_5 = GreaterThan(64);
    r_gt_5.in[0] <== r;
    r_gt_5.in[1] <== 5;

    signal pe <== p1_is_0.out * r_gt_5.out;

    // Raw score parts
    signal baseScore <== 100 * bp + 20 * ts;

    // Apply penalty with clamp at zero:
    // if pe = 0 -> out = baseScore
    // if pe = 1 -> out = max(baseScore - 50, 0)
    component base_ge_50 = GreaterEqThan(64);
    base_ge_50.in[0] <== baseScore;
    base_ge_50.in[1] <== 50;

    signal penalizedClamped <== base_ge_50.out * (baseScore - 50);
    signal noPenaltySel <== 1 - pe;

    out <== noPenaltySel * baseScore + pe * penalizedClamped;
}

component main = iterated_game_memory_score();

