import { IsZero } from "circomlib";
import { LessThan } from "circomlib";
import { Div } from "circomlib";

// Define the template
template validator_slashing_weight() {
  // Define signals
  signal input bal;
  signal input ts;
  signal input ta;
  signal output out;

  // Define intermediate signals
  signal ta_zero;
  signal p;
  signal p_lt_bal;

  // Zero check constraint
  component isZero = IsZero(64);
  isZero.in <== ta;
  ta_zero <== isZero.out;

  // Slashing weight calculation constraint
  component div = Div(64, 64);
  div.in[0] <== bal * 3 * ts;
  div.in[1] <== ta;
  div.in[2] <== ta_zero;
  p <== div.out;

  // Less-than constraint
  component lessThan = LessThan(64);
  lessThan.in[0] <== p;
  lessThan.in[1] <== bal;
  p_lt_bal <== lessThan.out;

  // Output selection constraint
  out <== ta_zero * 0 + (1 - ta_zero) * (p_lt_bal * p + (1 - p_lt_bal) * bal);
}

// Define the main component
component main = validator_slashing_weight();

