template ShuffleIntegrityLogic() {
    signal input c0;
    signal input c1;
    signal input c2;
    signal input c3;
    signal input c4;
    signal input s0;
    signal input s1;
    signal input s2;
    signal input s3;
    signal input s4;
    signal input sd;
    signal output out;

    // Check sum equality: c0+c1+c2+c3+c4 == s0+s1+s2+s3+s4
    signal c_sum <== c0 + c1 + c2 + c3 + c4;
    signal s_sum <== s0 + s1 + s2 + s3 + s4;
    signal sum_check <== (c_sum == s_sum) ? 1 : 0;

    // If sum check fails, return 0
    signal sum_fail <== 1 - sum_check;
    signal sum_fail_out <== sum_fail * 0;

    // Check sum of squares equality: c0^2+c1^2+c2^2+c3^2+c4^2 == s0^2+s1^2+s2^2+s3^2+s4^2
    signal c0_sq <== c0 * c0;
    signal c1_sq <== c1 * c1;
    signal c2_sq <== c2 * c2;
    signal c3_sq <== c3 * c3;
    signal c4_sq <== c4 * c4;
    signal c_sq_sum <== c0_sq + c1_sq + c2_sq + c3_sq + c4_sq;

    signal s0_sq <== s0 * s0;
    signal s1_sq <== s1 * s1;
    signal s2_sq <== s2 * s2;
    signal s3_sq <== s3 * s3;
    signal s4_sq <== s4 * s4;
    signal s_sq_sum <== s0_sq + s1_sq + s2_sq + s3_sq + s4_sq;

    signal sq_sum_check <== (c_sq_sum == s_sq_sum) ? 1 : 0;
    signal sq_sum_fail <== 1 - sq_sum_check;
    signal sq_sum_fail_out <== sq_sum_fail * 0;

    // Combined failure check
    signal both_checks_pass <== sum_check * sq_sum_check;
    signal any_fail <== 1 - both_checks_pass;

    // If any check fails, return 0
    signal failure_out <== any_fail * 0;

    // If checks pass, continue with the logic
    signal checks_pass <== both_checks_pass;

    // Check if any c_i equals s0
    signal c0_eq_s0 <== (c0 == s0) ? 1 : 0;
    signal c1_eq_s0 <== (c1 == s0) ? 1 : 0;
    signal c2_eq_s0 <== (c2 == s0) ? 1 : 0;
    signal c3_eq_s0 <== (c3 == s0) ? 1 : 0;
    signal c4_eq_s0 <== (c4 == s0) ? 1 : 0;
    signal any_eq_s0 <== c0_eq_s0 + c1_eq_s0 + c2_eq_s0 + c3_eq_s0 + c4_eq_s0;
    signal iv <== (any_eq_s0 > 0) ? 100 : 0;

    // Calculate inversions in s array
    signal s_array[5];
    s_array[0] <== s0;
    s_array[1] <== s1;
    s_array[2] <== s2;
    s_array[3] <== s3;
    s_array[4] <== s4;

    signal inv <== 0;

    // Manual unrolling of nested loops
    component cmp_0_1 = LessThan(64);
    cmp_0_1.in[0] <== s_array[1];
    cmp_0_1.in[1] <== s_array[0];
    inv = inv + cmp_0_1.out;

    component cmp_0_2 = LessThan(64);
    cmp_0_2.in[0] <== s_array[2];
    cmp_0_2.in[1] <== s_array[0];
    inv = inv + cmp_0_2.out;

    component cmp_0_3 = LessThan(64);
    cmp_0_3.in[0] <== s_array[3];
    cmp_0_3.in[1] <== s_array[0];
    inv = inv + cmp_0_3.out;

    component cmp_0_4 = LessThan(64);
    cmp_0_4.in[0] <== s_array[4];
    cmp_0_4.in[1] <== s_array[0];
    inv = inv + cmp_0_4.out;

    component cmp_1_2 = LessThan(64);
    cmp_1_2.in[0] <== s_array[2];
    cmp_1_2.in[1] <== s_array[1];
    inv = inv + cmp_1_2.out;

    component cmp_1_3 = LessThan(64);
    cmp_1_3.in[0] <== s_array[3];
    cmp_1_3.in[1] <== s_array[1];
    inv = inv + cmp_1_3.out;

    component cmp_1_4 = LessThan(64);
    cmp_1_4.in[0] <== s_array[4];
    cmp_1_4.in[1] <== s_array[1];
    inv = inv + cmp_1_4.out;

    component cmp_2_3 = LessThan(64);
    cmp_2_3.in[0] <== s_array[3];
    cmp_2_3.in[1] <== s_array[2];
    inv = inv + cmp_2_3.out;

    component cmp_2_4 = LessThan(64);
    cmp_2_4.in[0] <== s_array[4];
    cmp_2_4.in[1] <== s_array[2];
    inv = inv + cmp_2_4.out;

    component cmp_3_4 = LessThan(64);
    cmp_3_4.in[0] <== s_array[4];
    cmp_3_4.in[1] <== s_array[3];
    inv = inv + cmp_3_4.out;

    // Final result: inv + iv if checks pass, 0 otherwise
    signal success_result <== inv + iv;
    out <== checks_pass * success_result + failure_out;
}

