template Divide(n) {
    signal input in[2];
    signal output out;

    component rangeCheck = Num2Bits(n);
    rangeCheck.in <== in[0] - out * in[1];
    out * in[1] + rangeCheck.out === in[0];
    component lt = LessThan(n);
    lt.in[0] <== rangeCheck.out;
    lt.in[1] <== in[1];
    lt.out === 1;
}

template Modulo(n) {
    signal input in[2];
    signal output out;

    component div = Divide(n);
    div.in[0] <== in[0];
    div.in[1] <== in[1];
    out <== in[0] - div.out * in[1];
}

template MultDiv(n) {
    signal input a;
    signal input b;
    signal input c;
    signal input d;
    signal output out;

    component rangeCheck = Num2Bits(n);
    rangeCheck.in <== a * b * c - out * d;
    out * d + rangeCheck.out === a * b * c;
    component lt = LessThan(n);
    lt.in[0] <== rangeCheck.out;
    lt.in[1] <== d;
    lt.out === 1;
}

template SingleDecayStep() {
    signal input prev_cr;
    signal input step_index;
    signal input total_steps;
    signal output next_cr;

    component lt = LessThan(64);
    lt.in[0] <== step_index;
    lt.in[1] <== total_steps;
    signal should_execute <== lt.out;

    component halve = Divide(128);
    halve.in[0] <== prev_cr * 50;
    halve.in[1] <== 100;
    signal halved_cr <== halve.out;

    component lt10 = LessThan(64);
    lt10.in[0] <== halved_cr;
    lt10.in[1] <== 10;
    signal break_condition <== lt10.out;

    signal continue_execution <== should_execute * (1 - break_condition);
    next_cr <== continue_execution * halved_cr + (1 - continue_execution) * prev_cr;
}

template liquidity_mining_decay() {
    signal input br;
    signal input tp;
    signal input hp;
    signal input bm;
    signal output fr;

    component isZero = IsZero();
    isZero.in <== hp;

    signal nonZeroHP <== 1 - isZero.out;

    component div = Divide(128);
    div.in[0] <== tp;
    div.in[1] <== hp;
    signal st <== div.out;

    signal cr_init <== br;

    var n = 10;
    component decay[n];
    for (var i = 0; i < n; i++) {
        decay[i] = SingleDecayStep();
        if (i == 0) {
            decay[i].prev_cr <== cr_init;
        } else {
            decay[i].prev_cr <== decay[i-1].next_cr;
        }
        decay[i].step_index <== i;
        decay[i].total_steps <== st;
    }

    signal cr_after_loop <== decay[n-1].next_cr;

    component mod = Modulo(128);
    mod.in[0] <== tp;
    mod.in[1] <== hp;
    signal rem <== mod.out;

    component numerator = MultDiv(256);
    numerator.a <== cr_after_loop;
    numerator.b <== rem;
    numerator.c <== 50;
    numerator.d <== hp * 100;
    signal d <== numerator.out;

    signal cr_minus_d <== cr_after_loop - d;

    component finalMultDiv = MultDiv(256);
    finalMultDiv.a <== cr_minus_d;
    finalMultDiv.b <== bm;
    finalMultDiv.c <== 1;
    finalMultDiv.d <== 100;
    signal raw_fr <== finalMultDiv.out;

    fr <== nonZeroHP * raw_fr;
}

component main = liquidity_mining_decay();

template stack_rpn_calculator() {
    // Declare input signals
    signal input o0;
    signal input o1;
    signal input o2;
    signal input o3;
    signal input o4;

    // Declare output signals
    signal output out;

    // Declare a component to represent the stack
    component stack[5];

    // Initialize the stack with zeros
    for (var i = 0; i < 5; i++) {
        stack[i] = 0;
    }

    // Initialize the top of the stack to -1
    var top = -1;

    // Define a component to represent the operations
    component ops[5];

    // Initialize the operations with the input values
    ops[0] = o0;
    ops[1] = o1;
    ops[2] = o2;
    ops[3] = o3;
    ops[4] = o4;

    // Define a component to represent the result
    component res;

    // Iterate over the operations
    for (var i = 0; i < 5; i++) {
        // Get the current operation
        var v = ops[i];

        // If the operation is positive, push it onto the stack
        if (v > 0) {
            top++;
            stack[top] = v;
        }
        // If the operation is negative, pop two values from the stack, perform the operation, and push the result back onto the stack
        else if (v < 0) {
            // Get the top two values from the stack
            var v2 = stack[top];
            top--;
            var v1 = stack[top];
            top--;

            // Perform the operation
            if (v == -1) {
                res = v1 + v2;
            } else if (v == -2) {
                res = v1 - v2;
            } else if (v == -3) {
                res = v1 * v2;
            }

            // Push the result back onto the stack
            top++;
            stack[top] = res;
        }
    }

    // The final result is the top value on the stack plus the number of operations that were not pushed onto the stack
    out <== stack[0] + top;
}

