template CustomIsZero() {
    signal input in;
    signal output out;

    signal inv <-- 1 / (in + (in == 0));
    out <== 1 - (in * inv);
    in * (1 - out) === 0;
}

template DecayLoop() {
    signal input in_cr;
    signal input in_st;
    signal output out_cr;

    signal isStZero <== CustomIsZero();
    isStZero.in <== in_st;

    signal new_cr <== in_cr * 50 \ 100;

    component lt10 = LessThan(64);
    lt10.in[0] <== new_cr;
    lt10.in[1] <== 10;

    signal continue_cr <== (1 - lt10.out) * new_cr + lt10.out * in_cr;

    component next = DecayLoop();
    next.in_cr <== continue_cr;
    next.in_st <== in_st - 1;

    out_cr <== isStZero.out * in_cr + (1 - isStZero.out) * next.out_cr;
}

template LiquidityMiningDecay() {
    signal input br;
    signal input tp;
    signal input hp;
    signal input bm;
    signal output fr;

    signal isHpZero <== CustomIsZero();
    isHpZero.in <== hp;

