// Assumes IntDivide(n) is available, following the style of the retrieved templates.
template aave_v3_interest_logic() {
    signal input d;
    signal input r;
    signal input b;
    signal input s1;
    signal input s2;
    signal input opt;

    signal output out;

    // if r == 0 { return b }
    component rIsZero = IsZero();
    rIsZero.in <== r;

    signal safeR <== r + rIsZero.out;

    // u := (d * 10000) / r
    signal u;
    (u, _) <== IntDivide(64)(d * 10000, safeR);

    // if u <= opt { br = b + (u * s1 / opt) } else { br = b + s1 + ((u-opt)*s2/(10000-opt)) }
    component uLeOpt = LessEqThan(64);
    uLeOpt.in[0] <== u;
    uLeOpt.in[1] <== opt;

    component uGtOpt = GreaterThan(64);
    uGtOpt.in[0] <== u;
    uGtOpt.in[1] <== opt;

    component optIsZero = IsZero();
    optIsZero.in <== opt;
    signal safeOpt <== opt + optIsZero.out;

    signal brLowPart;
    (brLowPart, _) <== IntDivide(64)(u * s1, safeOpt);
    signal brLow <== b + brLowPart;

    signal denomHigh <== 10000 - opt;
    component denomHighIsZero = IsZero();
    denomHighIsZero.in <== denomHigh;
    signal safeDenomHigh <== denomHigh + denomHighIsZero.out;

    signal diffOpt <== uGtOpt.out * (u - opt);
    signal brHighPart;
    (brHighPart, _) <== IntDivide(64)(diffOpt * s2, safeDenomHigh);
    signal brHigh <== b + s1 + brHighPart;

    signal br <== uLeOpt.out * brLow + uGtOpt.out * brHigh;

    // sr := ((br * u) / 10000 * 9000) / 10000
    signal srBase;
    (srBase, _) <== IntDivide(64)(br * u, 10000);

    signal sr;
    (sr, _) <== IntDivide(64)(srBase * 9000, 10000);

    // rp := 0;
    // if u > 9500 { rp = (u-9500)*100 } else if u > 8000 { rp = (u-8000)*20 }
    component uGt9500 = GreaterThan(64);
    uGt9500.in[0] <== u;
    uGt9500.in[1] <== 9500;

    component uGt8000 = GreaterThan(64);
    uGt8000.in[0] <== u;
    uGt8000.in[1] <== 8000;

    signal rpHigh <== uGt9500.out * (u - 9500) * 100;
    signal rpMidSel <== uGt8000.out * (1 - uGt9500.out);
    signal rpMid <== rpMidSel * (u - 8000) * 20;
    signal rp <== rpHigh + rpMid;

    // res := br + sr + rp
    signal res <== br + sr + rp;

    // if res > 1000000 { return 1000000 }
    component resGtCap = GreaterThan(64);
    resGtCap.in[0] <== res;
    resGtCap.in[1] <== 1000000;

    signal cappedRes <== resGtCap.out * 1000000 + (1 - resGtCap.out) * res;

    // if r == 0 return b else return cappedRes
    out <== rIsZero.out * b + (1 - rIsZero.out) * cappedRes;
}

