    v1_1 <== stack[currentTop1 - 1];

    res1 <== 
        op1Add.out * (v1_1 + v2_1) +
        op1Sub.out * (v1_1 - v2_1) +
        op1Mul.out * (v1_1 * v2_1);

    // If it's an operation, update stack
    signal isOp1;
    isOp1 <== isNegative1.out;

    signal updatedTop1;
    updatedTop1 <== currentTop1 - 2 + isOp1;

    // Update stack for operation case
    stack[updatedTop1] <== (1 - isOp1) * stack[newTop1] + isOp1 * res1;

    // For positions that are not written, they keep their previous value
    // We need to handle all stack positions explicitly
    signal tempStack1_0;
    signal tempStack1_1;
    signal tempStack1_2;
    signal tempStack1_3;
    signal tempStack1_4;

    tempStack1_0 <== (1 - isPositive1.out) * (1 - isOp1) * stack[0] + 
                      isPositive1.out * (newTop1 == 0 ? newVal1 : stack[0]) +
                      isOp1 * (updatedTop1 == 0 ? res1 : stack[0]);

    tempStack1_1 <== (1 - isPositive1.out) * (1 - isOp1) * stack[1] + 
                      isPositive1.out * (newTop1 == 1 ? newVal1 : stack[1]) +
                      isOp1 * (updatedTop1 == 1 ? res1 : stack[1]);

    tempStack1_2 <== (1 - isPositive1.out) * (1 - isOp1) * stack[2] + 
                      isPositive1.out * (newTop1 == 2 ? newVal1 : stack[2]) +
                      isOp1 * (updatedTop1 == 2 ? res1 : stack[2]);

    tempStack1_3 <== (1 - isPositive1.out) * (1 - isOp1) * stack[3] + 
                      isPositive1.out * (newTop1 == 3 ? newVal1 : stack[3]) +
                      isOp1 * (updatedTop1 == 3 ? res1 : stack[3]);

    tempStack1_4 <== (1 - isPositive1.out) * (1 - isOp1) * stack[4] + 
                      isPositive1.out * (newTop1 == 4 ? newVal1 : stack[4]) +
                      isOp1 * (updatedTop1 == 4 ? res1 : stack[4]);

    stack[0] <== tempStack1_0;
    stack[1] <== tempStack1_1;
    stack[2] <== tempStack1_2;
    stack[3] <== tempStack1_3;
    stack[4] <== tempStack1_4;

    top <== (1 - isOp1) * newTop1 + isOp1 * updatedTop1;

    // Process o2
    component isPositive2 = IsPositive();
    isPositive2.in <== o2;
    component isNegative2 = IsPositive();
    isNegative2.in <== -o2;

    signal currentTop2;
    currentTop2 <== top;

    component op2Add = Eq();
    op2Add.a <== o2;
    op2Add.b <== -1;

    component op2Sub = Eq();
    op2Sub.a <== o2;
    op2Sub.b <== -2;

    component op2Mul = Eq();
    op2Mul.a <== o2;
    op2Mul.b <== -3;

    signal v2_2;
    signal v1_2;
    signal res2;

    v2_2 <== stack[currentTop2];
    v1_2 <== stack[currentTop2 - 1];

    res2 <== 
        op2Add.out * (v1_2 + v2_2) +
        op2Sub.out * (v1_2 - v2_2) +
        op2Mul.out * (v1_2 * v2_2);

    signal isOp2;
    isOp2 <== isNegative2.out;

    signal newTop2;
    newTop2 <== currentTop2 + isPositive2.out;
    signal newVal2;
    newVal2 <== isPositive2.out * o2;

    signal updatedTop2;
    updatedTop2 <== currentTop2 - 2 + isOp2;

    signal tempStack2_0;
    signal tempStack2_1;
    signal tempStack2_2;
    signal tempStack2_3;
    signal tempStack2_4;

    tempStack2_0 <== (1 - isPositive2.out) * (1 - isOp2) * stack[0] + 
                      isPositive2.out * (newTop2 == 0 ? newVal2 : stack[0]) +
                      isOp2 * (updatedTop2 == 0 ? res2 : stack[0]);

    tempStack2_1 <== (1 - isPositive2.out) * (1 - isOp2) * stack[1] + 
                      isPositive2.out * (newTop2 == 1 ? newVal2 : stack[1]) +
                      isOp2 * (updatedTop2 == 1 ? res2 : stack[1]);

    tempStack2_2 <== (1 - isPositive2.out) * (1 - isOp2) * stack[2] + 
                      isPositive2.out * (newTop2 == 2 ? newVal2 : stack[2]) +
                      isOp2 * (updatedTop2 == 2 ? res2 : stack[2]);

    tempStack2_3 <== (1 - isPositive2.out) * (1 - isOp2) * stack[3] + 
                      isPositive2.out * (newTop2 == 3 ? newVal2 : stack[3]) +
                      isOp2 * (updatedTop2 == 3 ? res2 : stack[3]);

    tempStack2_4 <== (1 - isPositive2.out) * (1 - isOp2) * stack[4] + 
                      isPositive2.out * (newTop2 == 4 ? newVal2 : stack[4]) +
                      isOp2 * (updatedTop2 == 4 ? res2 : stack[4]);

    stack[0] <== tempStack2_0;
    stack[1] <== tempStack2_1;
    stack[2] <== tempStack2_2;
    stack[3] <== tempStack2_3;
    stack[4] <== tempStack2_4;

    top <== (1 - isOp2) * newTop2 + isOp2 * updatedTop2;

    // Process o3
    component isPositive3 = IsPositive();
    isPositive3.in <== o3;
    component isNegative3 = IsPositive();
    isNegative3.in <== -o3;

    signal currentTop3;
    currentTop3 <== top;

    component op3Add = Eq();
    op3Add.a <== o3;
    op3Add.b <== -1;

    component op3Sub = Eq();
    op3Sub.a <== o3;
    op3Sub.b <== -2;

    component op3Mul = Eq();
    op3Mul.a <== o3;
    op3Mul.b <== -3;

    signal v2_3;
    signal v1_3;
    signal res3;

    v2_3 <== stack[currentTop3];
    v1_3 <== stack[currentTop3 - 1];

    res3 <== 
        op3Add.out * (v1_3 + v2_3) +
        op3Sub.out * (v1_3 - v2_3) +
        op3Mul.out * (v1_3 * v2_3);

    signal isOp3;
    isOp3 <== isNegative3.out;

    signal newTop3;
    newTop3 <== currentTop3 + isPositive3.out;
    signal newVal3;
    newVal3 <== isPositive3.out * o3;

    signal updatedTop3;
    updatedTop3 <== currentTop3 - 2 + isOp3;

    signal tempStack3_0;
    signal tempStack3_1;
    signal tempStack3_2;
    signal tempStack3_3;
    signal tempStack3_4;

    tempStack3_0 <== (1 - isPositive3.out) * (1 - isOp3) * stack[0] + 
                      isPositive3.out * (newTop3 == 0 ? newVal3 : stack[0]) +
                      isOp3 * (updatedTop3 == 0 ? res3 : stack[0]);

    tempStack3_1 <== (1 - isPositive3.out) * (1 - isOp3) * stack[1] + 
                      isPositive3.out * (newTop3 == 1 ? newVal3 : stack[1]) +
                      isOp3 * (updatedTop3 == 1 ? res3 : stack[1]);

    tempStack3_2 <== (1 - isPositive3.out) * (1 - isOp3) * stack[2] + 
                      isPositive3.out * (newTop3 == 2 ? newVal3 : stack[2]) +
                      isOp3 * (updatedTop3 == 2 ? res3 : stack[2]);

    tempStack3_3 <== (1 - isPositive3.out) * (1 - isOp3) * stack[3] + 
                      isPositive3.out * (newTop3 == 3 ? newVal3 : stack[3]) +
                      isOp3 * (updatedTop3 == 3 ? res3 : stack[3]);

    tempStack3_4 <== (1 - isPositive3.out) * (1 - isOp3) * stack[4] + 
                      isPositive3.out * (newTop3 == 4 ? newVal3 : stack[4]) +
                      isOp3 * (updatedTop3 == 4 ? res3 : stack[4]);

    stack[0] <== tempStack3_0;
    stack[1] <== tempStack3_1;
    stack[2] <== tempStack3_2;
    stack[3] <== tempStack3_3;
    stack[4] <== tempStack3_4;

    top <== (1 - isOp3) * newTop3 + isOp3 * updatedTop3;

    // Process o4
    component isPositive4 = IsPositive();
    isPositive4.in <== o4;
    component isNegative4 = IsPositive();
    isNegative4.in <== -o4;

    signal currentTop4;
    currentTop4 <== top;

    component op4Add = Eq();
    op4Add.a <== o4;
    op4Add.b <== -1;

    component op4Sub = Eq();
    op4Sub.a <== o4;
    op4Sub.b <== -2;

    component op4Mul = Eq();
    op4Mul.a <== o4;
    op4Mul.b <== -3;

    signal v2_4;
    signal v1_4;
    signal res4;

    v2_4 <== stack[currentTop4];
    v1_4 <== stack[currentTop4 - 1];

    res4 <== 
        op4Add.out * (v1_4 + v2_4) +
        op4Sub.out * (v1_4 - v2_4) +
        op4Mul.out * (v1_4 * v2_4);

    signal isOp4;
    isOp4 <== isNegative4.out;

    signal newTop4;
    newTop4 <== currentTop4 + isPositive4.out;
    signal newVal4;
    newVal4 <== isPositive4.out * o4;

    signal updatedTop4;
    updatedTop4 <== currentTop4 - 2 + isOp4;

    signal tempStack4_0;
    signal tempStack4_1;
    signal tempStack4_2;
    signal tempStack4_3;
    signal tempStack4_4;

    tempStack4_0 <== (1 - isPositive4.out) * (1 - isOp4) * stack[0] + 
                      isPositive4.out * (newTop4 == 0 ? newVal4 : stack[0]) +
                      isOp4 * (updatedTop4 == 0 ? res4 : stack[0]);

    tempStack4_1 <== (1 - isPositive4.out) * (1 - isOp4) * stack[1] + 
                      isPositive4.out * (newTop4 == 1 ? newVal4 : stack[1]) +
                      isOp4 * (updatedTop4 == 1 ? res4 : stack[1]);

    tempStack4_2 <== (1 - isPositive4.out) * (1 - isOp4) * stack[2] + 
                      isPositive4.out * (newTop4 == 2 ? newVal4 : stack[2]) +
                      isOp4 * (updatedTop4 == 2 ? res4 : stack[2]);

    tempStack4_3 <== (1 - isPositive4.out) * (1 - isOp4) * stack[3] + 
                      isPositive4.out * (newTop4 == 3 ? newVal4 : stack[3]) +
                      isOp4 * (updatedTop4 == 3 ? res4 : stack[3]);

    tempStack4_4 <== (1 - isPositive4.out) * (1 - isOp4) * stack[4] + 
                      isPositive4.out * (newTop4 == 4 ? newVal4 : stack[4]) +
                      isOp4 * (updatedTop4 == 4 ? res4 : stack[4]);

    stack[0] <== tempStack4_0;
    stack[1] <== tempStack4_1;
    stack[2] <== tempStack4_2;
    stack[3] <== tempStack4_3;
    stack[4] <== tempStack4_4;

    top <== (1 - isOp4) * newTop4 + isOp4 * updatedTop4;

    // Final output: stack[0] + top
    out <== stack[0] + top;
}

// Helper template for checking if a number is positive
template IsPositive() {
    signal input in;
    signal output out;

    component gte = GreaterThan(64);
    gte.in[0] <== in;
    gte.in[1] <== 0;
    out <== gte.out;
}

// Helper template for equality check
template Eq() {
    signal input a;
    signal input b;
    signal output out;

    signal diff;
    diff <== a - b;
    component isZero = IsZero();
    isZero.in <== diff;
    out <== 1 - isZero.out;
}

