template iterated_game_memory_score() {
    // Public inputs
    signal input p1;
    signal input p2;
    signal input h1;
    signal input h2;
    signal input h3;
    signal input r;

    // Output
    signal output out;

    // Enforce p1, p2 are bits
    p1 * (p1 - 1) === 0;
    p2 * (p2 - 1) === 0;

    // Equality indicators (direct assignment since p1,p2 are bits)
    signal eq_p1_1;
    signal eq_p2_1;
    signal eq_p1_0;
    signal eq_p2_0;

    eq_p1_1 <== p1;
    eq_p1_0 <== 1 - p1;
    eq_p2_1 <== p2;
    eq_p2_0 <== 1 - p2;

    // Boolean constraints (redundant due to above, but included for clarity)
    eq_p1_1 * (eq_p1_1 - 1) === 0;
    eq_p2_1 * (eq_p2_1 - 1) === 0;
    eq_p1_0 * (eq_p1_0 - 1) === 0;
    eq_p2_0 * (eq_p2_0 - 1) === 0;

    // AND conditions
    signal and1;
    signal and2;
    signal and3;

    and1 <== eq_p1_1 * eq_p2_1;   // p1=1, p2=1
    and2 <== eq_p1_1 * eq_p2_0;   // p1=1, p2=0
    and3 <== eq_p1_0 * eq_p2_1;   // p1=0, p2=1

    // Selection logic (mutually exclusive)
    signal sel1;
    signal sel2;
    signal sel3;

    sel1 <== and1;
    sel2 <== and2 * (1 - sel1);
    sel3 <== and3 * (1 - sel1) * (1 - sel2);

    // Base points
    signal bp;
    bp <== 3*sel1 + 0*sel2 + 5*sel3 + 1*(1 - sel1 - sel2 - sel3);

    // Total history score
    signal ts;
    ts <== h1 + h2 + h3;

    // Penalty condition: p1 == 0 && r > 5
    // Compute gt_r_5 = (r > 5) ? 1 : 0 using LessThan
    component gtComp = LessThan(16);
    gtComp.in[0] <== 5;
    gtComp.in[1] <== r;
    signal gt_r_5 <== gtComp.out;  // 1 if 5 < r, i.e., r > 5

    // Boolean constraint for gt_r_5
    gt_r_5 * (gt_r_5 - 1) === 0;

    signal pe;
    pe <== eq_p1_0 * gt_r_5;

    // Final score before clamp
    signal fs;
    fs <== bp * 100 + ts * 20 - pe * 50;

    // Clamp negative scores to zero: out = max(0, fs)
    // Since fs can be negative, we use offset method for comparison
    // Assume fs >= -100, so fs + 100 >= 0
    signal fs_offset;
    fs_offset <== fs + 100;

    component ltComp = LessThan(16);
    ltComp.in[0] <== fs_offset;
    ltComp.in[1] <== 100;  // fs + 100 < 100  => fs < 0
    signal lt_fs_0 <== ltComp.out;

    // Boolean constraint
    lt_fs_0 * (lt_fs_0 - 1) === 0;

    // Output
    out <== (1 - lt_fs_0) * fs;

    // Additional constraint: if lt_fs_0=1, out=0
    out * lt_fs_0 === 0;
}

component main = iterated_game_memory_score();

template is_even() {
    signal input n;
    signal output out;

    // Use Num2Bits to convert the input to a bit vector
    signal bits <== Num2Bits(254)(n);

    // Check the sign bit (bit 0) to determine if the number is even
    signal is_even <== bits[0];

    // Use the Mux Formula to select the output
    out <== is_even * (1 - 2 * is_even) + 1;
}

