template anova_f_test_logic() {
    signal input g1s;
    signal input g1n;
    signal input g2s;
    signal input g2n;
    signal input tss;
    signal output out;

    signal m1;
    signal m2;
    signal gm;
    signal ssb;
    signal ssw;

    m1 <== g1s / g1n;
    m2 <== g2s / g2n;
    gm <== (g1s + g2s) / (g1n + g2n);

    ssb <== g1n * (m1 - gm) * (m1 - gm) + g2n * (m2 - gm) * (m2 - gm);
    ssw <== tss - ssb;

    component lte = LessEqThan(64);
    lte.in[0] <== ssw;
    lte.in[1] <== 0;

    signal sel;
    sel <== lte.out;

    signal inv;
    signal frac;
    signal expr;

    ssw * inv === 1 - sel;
    sel * ssw === 0;

    frac <== ssb * 100 * inv;
    expr <== frac + gm;

    out <== sel * gm + (1 - sel) * expr;
}

