template SafeDiv() {
    signal input numerator;
    signal input denominator;
    signal output quotient;
    signal output remainder;

    // Handle zero division
    component isZero = IsZero();
    isZero.in <== denominator;

    // For non-zero denominator: numerator = denominator * quotient + remainder
    // For zero denominator: quotient = 0, remainder = numerator
    signal safeDenominator <== denominator + isZero.out;

    quotient <-- numerator / safeDenominator;
    remainder <-- numerator % safeDenominator;

    // Verify the division
    numerator === denominator * quotient + remainder;
}

template EMA_Signal_Logic() {
    signal input p0;
    signal input p1;
    signal input p2;
    signal input p3;
    signal input p4;
    signal output out;

    // Constants
    var alpha = 40;
    var scale = 100;

    // Initialize EMA with first price scaled by 100
    signal ema <== p0 * scale;

    // Process remaining prices
    component div1 = SafeDiv();
    component div2 = SafeDiv();
    component div3 = SafeDiv();
    component div4 = SafeDiv();

    // EMA calculation for each step
    // ema = (price * alpha) + (ema * (100 - alpha) / 100)

    // Step 1: p1
    signal term1_1 <== p1 * alpha;
    signal term2_1 <== ema * (scale - alpha);
    div1.numerator <== term2_1;
    div1.denominator <== scale;
    ema <== term1_1 + div1.quotient;

    // Step 2: p2
    signal term1_2 <== p2 * alpha;
    signal term2_2 <== ema * (scale - alpha);
    div2.numerator <== term2_2;
    div2.denominator <== scale;
    ema <== term1_2 + div2.quotient;

    // Step 3: p3
    signal term1_3 <== p3 * alpha;
    signal term2_3 <== ema * (scale - alpha);
    div3.numerator <== term2_3;
    div3.denominator <== scale;
    ema <== term1_3 + div3.quotient;

    // Step 4: p4
    signal term1_4 <== p4 * alpha;
    signal term2_4 <== ema * (scale - alpha);
    div4.numerator <== term2_4;
    div4.denominator <== scale;
    ema <== term1_4 + div4.quotient;

    out <== ema;
}

