    // Output
    signal output out;

    // Intermediate signals
    signal ema0;
    signal ema1;
    signal ema2;
    signal ema3;
    signal ema4;

    // Constant alpha = 40
    var alpha = 40;
    var hundred = 100;
    var hundred_minus_alpha = 100 - alpha; // = 60

    // Constraint: ema0 == p0 * 100
    ema0 <== p0 * hundred;

    // Constraint: 100 * ema1 == 100 * p1 * alpha + ema0 * (100 - alpha)
    // Rearranged: ema1 == (p1 * alpha) + (ema0 * (100 - alpha) / 100)
