    // Constraint: 100 * ema2 == 100 * p2 * alpha + ema1 * (100 - alpha)
    hundred * ema2 <== hundred * p2 * alpha + ema1 * hundred_minus_alpha;

    // Constraint: 100 * ema3 == 100 * p3 * alpha + ema2 * (100 - alpha)
    hundred * ema3 <== hundred * p3 * alpha + ema2 * hundred_minus_alpha;

    // Constraint: 100 * ema4 == 100 * p4 * alpha + ema3 * (100 - alpha)
    hundred * ema4 <== hundred * p4 * alpha + ema3 * hundred_minus_alpha;

