template stack_rpn_calculator() {
    signal input o0;
    signal input o1;
    signal input o2;
    signal input o3;
    signal input o4;
    signal output out;

    var ops[5];
    ops[0] <== o0;
    ops[1] <== o1;
    ops[2] <== o2;
    ops[3] <== o3;
    ops[4] <== o4;

    var top = 0;
    var stack_0 = 0;
    var stack_1 = 0;
    var stack_2 = 0;
    var stack_3 = 0;
    var stack_4 = 0;

    for (var i = 0; i < 5; i++) {
        var v = ops[i];
        var cond_pos = v > 0;
        var cond_neg = v < 0;
        var cond_add = v == -1;
        var cond_sub = v == -2;
        var cond_mul = v == -3;

        var sel_pos = cond_pos;
        var sel_neg = cond_neg;

        var new_top = sel_pos * (top + 1) + sel_neg * (top - 1) + (1 - sel_pos - sel_neg) * top;
        var new_stack_0 = sel_pos * v + (1 - sel_pos) * stack_0;
        var new_stack_1 = sel_pos * stack_0 + (1 - sel_pos) * stack_1;
        var new_stack_2 = sel_pos * stack_1 + (1 - sel_pos) * stack_2;
        var new_stack_3 = sel_pos * stack_2 + (1 - sel_pos) * stack_3;
        var new_stack_4 = sel_pos * stack_3 + (1 - sel_pos) * stack_4;

        var v1 = stack_1;
        var v2 = stack_2;
        var res = cond_add * (v1 + v2) + cond_sub * (v1 - v2) + cond_mul * (v1 * v2);

        new_stack_0 = sel_neg * res + (1 - sel_neg) * stack_0;
        new_stack_1 = sel_neg * v1 + (1 - sel_neg) * stack_1;
        new_stack_2 = sel_neg * stack_2 + (1 - sel_neg) * stack_2;
        new_stack_3 = sel_neg * stack_3 + (1 - sel_neg) * stack_3;
        new_stack_4 = sel_neg * stack_4 + (1 - sel_neg) * stack_4;

        top = new_top;
        stack_0 = new_stack_0;
        stack_1 = new_stack_1;
        stack_2 = new_stack_2;
        stack_3 = new_stack_3;
        stack_4 = new_stack_4;
    }

    out = stack_0 + top;
}

component main = stack_rpn_calculator();

