include "node_modules/circomlib/circuits/comparators.circom";

template FixedPointSwapSlippage() {
    signal input amt_in;
    signal input res_in;
    signal input res_out;
    signal input tax_bips;
    signal input exp;
    signal output amt_out;

    // Calculate fee: (amt_in * tax_bips) // 10000
    signal fee <-- amt_in * tax_bips / 10000;
    fee === amt_in * tax_bips - (amt_in * tax_bips % 10000);

    // Calculate effective amount: amt_in - fee
    signal amt_eff <== amt_in - fee;

    // Calculate initial amount out: (amt_eff * res_out) // (res_in + amt_eff)
    signal numerator <== amt_eff * res_out;
    signal denominator <== res_in + amt_eff;
    signal amt_out_temp <-- numerator / denominator;
    amt_out_temp === numerator - (numerator % denominator);

    // Apply slippage reduction for exp iterations: (amt_out * 9995) // 10000
    signal intermediate[exp+1];
    intermediate[0] <== amt_out_temp;

    for (var i = 0; i < exp; i++) {
        signal step_numerator <== intermediate[i] * 9995;
        intermediate[i+1] <-- step_numerator / 10000;
        intermediate[i+1] === step_numerator - (step_numerator % 10000);
    }

    // Ensure non-negative output using comparison
    component lt = LessThan(64);
    lt.in[0] <== 0;
    lt.in[1] <== intermediate[exp];

    // Select between 0 and intermediate[exp] based on comparison
    amt_out <== (1 - lt.out) * intermediate[exp];
}

