template fixed_point_swap_slippage(exp) {
    signal input amt_in;
    signal input res_in;
    signal input res_out;
    signal input tax_bips;
    signal output out;

    // fee = (amt_in * tax_bips) // 10000
    signal fee;
    signal fee_rem;
    fee <-- (amt_in * tax_bips) \ 10000;
    fee_rem <-- (amt_in * tax_bips) % 10000;
    amt_in * tax_bips === fee * 10000 + fee_rem;

    component fee_rem_lt = LessThan(64);
    fee_rem_lt.in[0] <== fee_rem;
    fee_rem_lt.in[1] <== 10000;
    fee_rem_lt.out === 1;

    // amt_eff = amt_in - fee
    signal amt_eff <== amt_in - fee;

    // amt_out = (amt_eff * res_out) // (res_in + amt_eff)
    signal amt_out_0;
    signal amt_out_0_rem;
    amt_out_0 <-- (amt_eff * res_out) \ (res_in + amt_eff);
    amt_out_0_rem <-- (amt_eff * res_out) % (res_in + amt_eff);
    amt_eff * res_out === amt_out_0 * (res_in + amt_eff) + amt_out_0_rem;

    component amt_out_0_rem_lt = LessThan(252);
    amt_out_0_rem_lt.in[0] <== amt_out_0_rem;
    amt_out_0_rem_lt.in[1] <== res_in + amt_eff;
    amt_out_0_rem_lt.out === 1;

    // for i in range(exp):
    //     amt_out = (amt_out * 9995) // 10000
    signal amt_out_arr[exp + 1];
    amt_out_arr[0] <== amt_out_0;

    signal amt_out_rem[exp > 0 ? exp : 1];
    component amt_out_rem_lt[exp > 0 ? exp : 1];

    for (var i = 0; i < exp; i++) {
        amt_out_arr[i+1] <-- (amt_out_arr[i] * 9995) \ 10000;
        amt_out_rem[i] <-- (amt_out_arr[i] * 9995) % 10000;
        amt_out_arr[i] * 9995 === amt_out_arr[i+1] * 10000 + amt_out_rem[i];

        amt_out_rem_lt[i] = LessThan(64);
        amt_out_rem_lt[i].in[0] <== amt_out_rem[i];
        amt_out_rem_lt[i].in[1] <== 10000;
        amt_out_rem_lt[i].out === 1;
    }

    // if amt_out < 0: return 0
    // (In field arithmetic with valid positive inputs, amt_out is always >= 0)
    out <== amt_out_arr[exp];
}

