def ema_signal_logic(p0, p1, p2, p3, p4):
    prices = [p0, p1, p2, p3, p4]
    alpha = 40
    ema = prices[0] * 100
    for i in range(1, 5):
        ema = (prices[i] * alpha) + (ema * (100 - alpha) // 100)
    return int(ema)

