template ema_signal_logic() {
    signal input p0;
    signal input p1;
    signal input p2;
    signal input p3;
    signal input p4;
    signal output out;

    signal alpha <== 40;
    signal hundred <== 100;
    signal hundred_minus_alpha <== hundred - alpha;

    signal ema0 <== p0 * hundred;

    signal term1_1 <== p1 * alpha;
    signal term2_1 <== ema0 * hundred_minus_alpha;
    signal ema1;
    ema1 * hundred === term1_1 * hundred + term2_1;

    signal term1_2 <== p2 * alpha;
    signal term2_2 <== ema1 * hundred_minus_alpha;
    signal ema2;
    ema2 * hundred === term1_2 * hundred + term2_2;

    signal term1_3 <== p3 * alpha;
    signal term2_3 <== ema2 * hundred_minus_alpha;
    signal ema3;
    ema3 * hundred === term1_3 * hundred + term2_3;

    signal term1_4 <== p4 * alpha;
    signal term2_4 <== ema3 * hundred_minus_alpha;
    signal ema4;
    ema4 * hundred === term1_4 * hundred + term2_4;

    out <== ema4;
}

