template XorCipherBlock() {
    signal input p1;
    signal input p2;
    signal input k1;
    signal input k2;
    signal output out;

    // Decompose inputs into bits (64-bit assumed)
    component p1_bits = Num2Bits(64);
    component k1_bits = Num2Bits(64);
    component p2_bits = Num2Bits(64);
    component k2_bits = Num2Bits(64);

    p1_bits.in <== p1;
    k1_bits.in <== k1;
    p2_bits.in <== p2;
    k2_bits.in <== k2;

    // Compute p1 ^ k1
    signal xor1[64];
    signal x1; // reconstructed value of p1 ^ k1

    for (var i = 0; i < 64; i++) {
        // XOR: a + b - 2*a*b
        xor1[i] <== p1_bits.out[i] + k1_bits.out[i] - 2 * p1_bits.out[i] * k1_bits.out[i];
    }

    // Reconstruct x1 from bits
    x1 <== sumBits(xor1);

    // Compute p2 ^ k2
    signal xor2[64];
    signal x2;

    for (var i = 0; i < 64; i++) {
        xor2[i] <== p2_bits.out[i] + k2_bits.out[i] - 2 * p2_bits.out[i] * k2_bits.out[i];
    }

    x2 <== sumBits(xor2);

    // Final output: (p1 ^ k1) * 100 + (p2 ^ k2)
    out <== x1 * 100 + x2;
}

// Helper function to convert bit array to integer
function sumBits(bits) {
    var res = 0;
    var power = 1;
    for (var i = 0; i < bits.length; i++) {
        res += bits[i] * power;
        power *= 2;
    }
    return res;
}

component main = XorCipherBlock();
